105.     ///
106.     /// # Description
107.     ///
108.     /// Allocates a frame.
109.     ///
110.     /// # Returns
111.     ///
112.     /// Upon success, the address of the allocated frame is returned. Upon failure, an error is
113.     /// returned instead.
114.     ///
115.     #[verus_verify(external_body)]
116.     #[verus_spec(result =>
117.         requires
118.             old(self).inv(),
119.         ensures
120.             final(self).inv(),
121.             match result {
122.                 Ok(frame) => {
123.                     &&& frame.inv()
124.                     &&& old(self)@.free_frames.contains(frame@)
125.                     &&& final(self)@ == FrameAllocView {
126.                         allocated_frames: old(self)@.allocated_frames.insert(frame@),
127.                         free_frames: old(self)@.free_frames.remove(frame@),
128.                         refcounts: old(self)@.refcounts.insert(frame@, 1int),
129.                     }
130.                 },
131.                 Err(_) => {
132.                     &&& final(self)@ == old(self)@
133.                     &&& old(self)@.free_frames.is_empty()
134.                 }
135.             },
136.     )]
137.     fn alloc(&mut self) -> Result<FrameAddress, Error> {
138.         let frame_number: usize = match self.bitmap.alloc() {
139.             Ok(index) => index,
140.             Err(error) => {
141.                 error!("{error:?}");
142.                 return Err(error);
143.             },
144.         };
145.         // Newly allocated frames have a single owner.
146.         debug_assert_eq!(self.refcount[frame_number], 0);
147.         self.refcount[frame_number] = 1;
148.         let frame_number: FrameNumber = match FrameNumber::from_raw_value(frame_number) {
149.             Some(frame_number) => frame_number,
150.             None => {
151.                 let reason: &str = "frame number is out of bounds";
152.                 error!("{reason:?}");
153.                 return Err(Error::new(ErrorCode::OutOfMemory, reason));
154.             },
155.         };
156. 
157.         // Attempt to convert the frame number to a frame address.
158.         match FrameAddress::from_frame_number(frame_number) {
159.             Ok(frame_address) => Ok(frame_address),
160.             Err(error) => {
161.                 error!("{error:?}");
162.                 Err(error)
163.             },
164.         }
165.     }
