168.     /// # Description
169.     ///
170.     /// Allocates `count` physically contiguous frames.
171.     ///
172.     /// # Parameters
173.     ///
174.     /// - `count`: Number of contiguous frames to allocate.
175.     ///
176.     /// # Returns
177.     ///
178.     /// Upon success, the base `FrameAddress` of the contiguous range is returned. Upon failure,
179.     /// an error is returned instead.
180.     ///
181.     #[verus_verify(external_body)]
182.     #[verus_spec(result =>
183.         requires
184.             old(self).inv(),
185.             count > 0,
186.         ensures
187.             final(self).inv(),
188.             match result {
189.                 Ok(base) => {
190.                     &&& base.inv()
191.                     &&& ({
192.                         let frames = Set::new(|addr: int|
193.                             exists|i: int| 0 <= i < count && addr == #[trigger] (base@ + i * spec_page_size())
194.                         );
195.                         &&& frames.subset_of(old(self)@.free_frames)
196.                         &&& final(self)@ == FrameAllocView {
197.                             allocated_frames: old(self)@.allocated_frames.union(frames),
198.                             free_frames: old(self)@.free_frames.difference(frames),
199.                             refcounts: old(self)@.refcounts.union_prefer_right(
200.                                 Map::new(|addr: int| frames.contains(addr), |addr: int| 1int)
201.                             ),
202.                         }
203.                     })
204.                 },
205.                 Err(_) => {
206.                     final(self)@ == old(self)@
207.                 }
208.             },
209.     )]
210.     fn alloc_contiguous(&mut self, count: usize) -> Result<FrameAddress, Error> {
211.         let frame_number: usize = match self.bitmap.alloc_range(count) {
212.             Ok(index) => index,
213.             Err(error) => {
214.                 error!("{error:?} (count={count})");
215.                 return Err(error);
216.             },
217.         };
218.         // Newly allocated frames have a single owner.
219.         for i in frame_number..frame_number + count {
220.             debug_assert_eq!(self.refcount[i], 0);
221.             self.refcount[i] = 1;
222.         }
